-- =====================================================================
-- Expense immutability
-- =====================================================================
-- `expenses` was the only financial table left without a guard: migration
-- `20261017000400_immutability_triggers` covers ten tables but not this one,
-- and the Expenses page performs a HARD delete (`expensesApi.remove` filters
-- the row out of the store and audits it as EXPENSE_DELETED). Two rules are
-- installed here.
--
-- 1. An expense generated by a loan repayment is not editable and not
--    deleteable. It exists only as the interest half of that repayment; the
--    repayment and its ledger entries are immutable, so the matching expense
--    must be too. To undo it, reverse the repayment.
--
-- 2. For every expense, `loanRepaymentId` and `category` are immutable once
--    created. Both are classification columns: changing `category` silently
--    rewrites historical reporting, and setting `loanRepaymentId` would
--    fabricate a link to a repayment that never produced this expense.
--    The remaining columns (channel, description, amountKobo, expenseDate,
--    updatedAt) stay editable, so ordinary book-keeping corrections still work.
--
-- NOTE: this deliberately does NOT turn `expenses` into a fully append-only
-- table, and it does not introduce a "void with reason". Ordinary expenses
-- can still be edited and deleted today; changing that is a product decision
-- tracked separately.
--
-- Prisma maps only *table* names via @@map; column names stay camelCase and
-- are therefore written as quoted camelCase identifiers below.

CREATE OR REPLACE FUNCTION fn_expense_immutability()
RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD."loanRepaymentId" IS NOT NULL THEN
      RAISE EXCEPTION
        'A loan-interest expense (loanRepaymentId=%) cannot be deleted; reverse the repayment instead.',
        OLD."loanRepaymentId";
    END IF;
    RETURN OLD;
  END IF;

  IF OLD."loanRepaymentId" IS NOT NULL THEN
    RAISE EXCEPTION
      'A loan-interest expense (loanRepaymentId=%) cannot be updated; reverse the repayment instead.',
      OLD."loanRepaymentId";
  END IF;

  IF NEW."loanRepaymentId" IS DISTINCT FROM OLD."loanRepaymentId" THEN
    RAISE EXCEPTION 'expenses.loanRepaymentId is immutable once created.';
  END IF;

  IF NEW.category IS DISTINCT FROM OLD.category THEN
    RAISE EXCEPTION
      'expenses.category is immutable once created (was %, attempted %).',
      OLD.category, NEW.category;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_expense_immutability
  BEFORE UPDATE OR DELETE ON expenses
  FOR EACH ROW EXECUTE FUNCTION fn_expense_immutability();

-- TRUNCATE bypasses row-level triggers, so it needs its own guard.
CREATE TRIGGER trg_expense_no_truncate
  BEFORE TRUNCATE ON expenses
  EXECUTE FUNCTION fn_raise_immutable();
